import {ScriptTarget,transpileModule,flattenDiagnosticMessageText} from 'typescript';
const targets=new Map([['es2015',ScriptTarget.ES2015],['es2020',ScriptTarget.ES2020]]);
export async function transform(input){
  if((input.compiler||'typescript')!=='typescript'||!targets.has(input.target))throw Error('Unsupported compiler/target');
  const emitted=transpileModule(input.source,{compilerOptions:{target:targets.get(input.target)},reportDiagnostics:true});
  const diagnostics=Array.from(emitted.diagnostics||[],diagnostic=>{const coordinates=diagnostic.file?.getLineAndCharacterOfPosition(diagnostic.start||0);return{message:flattenDiagnosticMessageText(diagnostic.messageText,'\n'),line:coordinates?coordinates.line+1:null,column:coordinates?coordinates.character+1:null};});
  return{code:diagnostics.length===0?emitted.outputText:'',diagnostics};
}
